-- ============================================================
-- boutique_pret_a_porter — Script de création et de peuplement (PostgreSQL)
-- Base transactionnelle d'une boutique en ligne de prêt-à-porter
-- (Femme / Homme / Enfant) — Projet fil rouge J7-J8
-- Aucun index n'est créé explicitement : seuls les index implicites des clés
-- primaires et de la contrainte UNIQUE (clients.email) sont générés par PostgreSQL.
-- Volumes : 8 000 clients, 500 produits, 50 000 commandes, 6 000 retours
-- Période : 01/09/2024 -> 31/08/2025 — généré par generer_boutique_pap.py
--
-- À exécuter en 2 étapes distinctes :
--
-- ÉTAPE 1 — Créer la base (une seule fois, connecté à une base par
-- défaut comme "postgres") :
--     CREATE DATABASE pret_porter;
--
-- ÉTAPE 2 — Se reconnecter à la base pret_porter, puis exécuter tout
-- le reste de ce script (le schéma "bronze" est créé ci-dessous) :
--     - psql   : \c pret_porter
--     - pgAdmin: ouvrir un nouveau Query Tool sur la base "pret_porter"
--                (clic droit sur pret_porter > Query Tool)
--
-- Toutes les tables sont créées dans le schéma "bronze" (et non "public").
-- ============================================================

CREATE SCHEMA IF NOT EXISTS bronze;

DROP TABLE IF EXISTS bronze.retours CASCADE;
DROP TABLE IF EXISTS bronze.lignes_commande CASCADE;
DROP TABLE IF EXISTS bronze.commandes CASCADE;
DROP TABLE IF EXISTS bronze.produits CASCADE;
DROP TABLE IF EXISTS bronze.clients CASCADE;

-- ============================================================
-- Schéma
-- ============================================================

CREATE TABLE bronze.clients (
    id_client          INT PRIMARY KEY,
    nom                VARCHAR(100) NOT NULL,
    prenom             VARCHAR(100) NOT NULL,
    email              VARCHAR(150) UNIQUE,
    ville              VARCHAR(100),
    date_inscription   DATE NOT NULL,
    genre              VARCHAR(20),
    date_naissance     DATE,
    code_postal        VARCHAR(5),
    region             VARCHAR(50),
    canal_acquisition  VARCHAR(50),
    optin_newsletter   BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE bronze.produits (
    id_produit            INT PRIMARY KEY,
    nom_produit           VARCHAR(200) NOT NULL,
    categorie             VARCHAR(100) NOT NULL,
    prix_unitaire         DECIMAL(10,2) NOT NULL CHECK (prix_unitaire >= 0),
    stock_actuel          INT NOT NULL CHECK (stock_actuel >= 0),
    sous_categorie        VARCHAR(100) NOT NULL,
    genre_cible           VARCHAR(20) NOT NULL,
    marque                VARCHAR(100) NOT NULL,
    matiere               VARCHAR(50),
    collection            VARCHAR(20) NOT NULL,
    cout_unitaire         DECIMAL(10,2) CHECK (cout_unitaire >= 0),
    date_ajout_catalogue  DATE NOT NULL,
    actif                 BOOLEAN NOT NULL DEFAULT TRUE
);

-- montant_total = somme des lignes (hors frais de livraison)
CREATE TABLE bronze.commandes (
    id_commande      INT PRIMARY KEY,
    id_client        INT NOT NULL,
    date_commande    DATE NOT NULL,
    statut           VARCHAR(20) CHECK (statut IN ('en_cours','expediee','livree','annulee')),
    montant_total    DECIMAL(10,2) CHECK (montant_total >= 0),
    canal_commande   VARCHAR(30),
    mode_paiement    VARCHAR(30),
    mode_livraison   VARCHAR(30),
    frais_livraison  DECIMAL(6,2) CHECK (frais_livraison >= 0),
    code_promo       VARCHAR(20),
    date_livraison   DATE,
    CONSTRAINT fk_commandes_client FOREIGN KEY (id_client) REFERENCES bronze.clients(id_client)
);

CREATE TABLE bronze.lignes_commande (
    id_ligne               INT PRIMARY KEY,
    id_commande            INT NOT NULL,
    id_produit             INT NOT NULL,
    quantite               INT NOT NULL CHECK (quantite > 0),
    prix_unitaire_facture  DECIMAL(10,2) NOT NULL,
    taille                 VARCHAR(10),
    couleur                VARCHAR(30),
    remise_pct             INT NOT NULL DEFAULT 0 CHECK (remise_pct BETWEEN 0 AND 100),
    CONSTRAINT fk_lignes_commande FOREIGN KEY (id_commande) REFERENCES bronze.commandes(id_commande),
    CONSTRAINT fk_lignes_produit FOREIGN KEY (id_produit) REFERENCES bronze.produits(id_produit)
);

CREATE TABLE bronze.retours (
    id_retour             INT PRIMARY KEY,
    id_ligne              INT NOT NULL,
    date_retour           DATE,
    motif                 VARCHAR(200),
    quantite_retournee    INT CHECK (quantite_retournee > 0),
    statut_remboursement  VARCHAR(20) CHECK (statut_remboursement IN ('en_attente','rembourse','refuse')),
    montant_rembourse     DECIMAL(10,2) CHECK (montant_rembourse >= 0),
    CONSTRAINT fk_retours_ligne FOREIGN KEY (id_ligne) REFERENCES bronze.lignes_commande(id_ligne)
);


