-- ---------- produits (500 lignes) ----------

-- ---------- commandes (50000 lignes) ----------

-- ---------- lignes_commande (111095 lignes) ----------

-- ---------- retours (6000 lignes) ----------


-- ============================================================
-- Vérification rapide
-- ============================================================
SELECT 'clients' AS table_name, COUNT(*) AS nb_lignes FROM bronze.clients
UNION ALL SELECT 'produits', COUNT(*) FROM bronze.produits
UNION ALL SELECT 'commandes', COUNT(*) FROM bronze.commandes
UNION ALL SELECT 'lignes_commande', COUNT(*) FROM bronze.lignes_commande
UNION ALL SELECT 'retours', COUNT(*) FROM bronze.retours;
